import { readdir, readFile, writeFile } from 'node:fs/promises'
import { join, resolve } from 'node:path'
import type {
  LlmsTxtPage,
  LlmsTxtRenderer,
  LlmsTxtSection,
  RspressPlugin,
} from '@rspress/core'
import { sidebar } from './sidebar.ts'

// The files for AI assistants: llms.txt (an index of the pages, in
// Markdown), llms-full.txt (every page in one file) and a .md version of
// each page, generated by Rspress (https://llmstxt.org). This module adds
// the rules an assistant trained on Dotpress 1 would get wrong, and cleans
// the twoslash markers out of the Markdown.

const SITE = 'https://dotpress.dev'

/** Rules for assistants, at the top of llms.txt and llms-full.txt. */
export const LLMS_GUIDANCE = `This documentation covers Dotpress 2. Dotpress 1 (the \`dotpress\` package, and \`@dotpress/auth\` 1.x) has a different API: do not use it, nor code written for it.

Dotpress 2 is in beta. Install \`@dotpress/auth\` with the \`beta\` tag, since its \`latest\` tag is still 1.x: \`npm install @dotpress/auth@beta\`.

Key rules:

- Declare routes with \`defineRoute()\` and Zod 4 schemas: the types of the request and of the response are inferred, never passed as generics.
- Handlers and middlewares return their errors (\`notFoundError()\`, \`forbiddenError()\`…): they do not throw them.
- The packages are ES modules, for Node.js 22.12 or later and TypeScript 5.5 or later, with \`strict\` enabled.
- Apps are tested in memory with \`@dotpress/testing\`, on Vitest.`

/** The pages an assistant can skip when its context is short. */
const isOptional = (page: LlmsTxtPage) =>
  /^\/(examples\/|reference\/migrate-from-v1|reference\/design-decisions\/)/.test(
    page.routePath
  )

/** The links of the sidebar, in reading order. */
const sidebarOrder = new Map(
  Object.values(sidebar)
    .flat()
    .flatMap((group) => ('items' in group ? group.items : []))
    .flatMap((item) => ('link' in item && item.link ? [item.link] : []))
    .map((link, index) => [link, index])
)
const byReadingOrder = (a: LlmsTxtPage, b: LlmsTxtPage) =>
  (sidebarOrder.get(a.routePath) ?? Infinity) -
  (sidebarOrder.get(b.routePath) ?? Infinity)

const pageLine = ({ title, link, description }: LlmsTxtPage) =>
  `- [${title}](${link})${description ? `: ${description}` : ''}`

/**
 * llms.txt: the default format of Rspress, with the rules above, the pages
 * outside the nav as a Deployment section, and an Optional section.
 */
export const renderLlmsTxt: LlmsTxtRenderer = ({
  title,
  description,
  sections,
}) => {
  const optional: LlmsTxtPage[] = []
  const main: LlmsTxtSection[] = []
  for (const section of sections) {
    const pages = section.pages.filter((page) => {
      if (!isOptional(page)) return true
      optional.push(page)
      return false
    })
    if (pages.length === 0) continue
    // Rspress puts the pages outside the nav in "Others": the deployment
    // guides. Another page there keeps "Others", which the check of the CI
    // rejects (scripts/check-llms.mjs).
    const deployment =
      section.title === 'Others' &&
      pages.every((page) => page.routePath.startsWith('/deployment/'))
    main.push(
      deployment
        ? { title: 'Deployment', pages: [...pages].sort(byReadingOrder) }
        : { title: section.title, pages }
    )
  }
  if (optional.length > 0) main.push({ title: 'Optional', pages: optional })

  return [
    `# ${title}`,
    `> ${description}`,
    LLMS_GUIDANCE,
    `The pages below are in Markdown. ${SITE}/llms-full.txt has the whole documentation in one large file.`,
    ...main.map(
      (section) =>
        `## ${section.title}\n\n${section.pages.map(pageLine).join('\n')}`
    ),
  ].join('\n\n')
}

/**
 * The Markdown of the twoslash code blocks, as it is read without the
 * site: no `twoslash` marker and no compiler directive. The code before
 * `// ---cut---`, hidden on the site, is kept: its imports tell where each
 * function comes from.
 */
export const cleanMarkdown = (markdown: string) => {
  const output: string[] = []
  let twoslash = false
  for (const line of markdown.split('\n')) {
    const fence = /^(\s*)```(\S*)(.*)$/.exec(line)
    if (fence !== null) {
      const [, indent = '', lang = '', meta = ''] = fence
      if (twoslash || lang === '') {
        twoslash = false
        output.push(line)
      } else {
        twoslash = /(^|\s)twoslash(\s|$)/.test(meta)
        output.push(
          `${indent}\`\`\`${lang}${meta.replace(/\s*\btwoslash\b/, '')}`
        )
      }
    } else if (twoslash && /^\s*\/\/ ---cut[\w-]*---\s*$/.test(line)) {
      // The hidden code and the shown code, apart.
      if (!/^\s*$|```/.test(output.at(-1) ?? '')) output.push('')
    } else if (!(twoslash && /^\s*\/\/ @\w+(:.*)?\s*$/.test(line))) {
      output.push(line)
    }
  }
  return output.join('\n')
}

const markdownFiles = async (directory: string): Promise<string[]> => {
  const entries = await readdir(directory, { withFileTypes: true })
  const files = await Promise.all(
    entries.map((entry) => {
      const path = join(directory, entry.name)
      if (entry.isDirectory()) return markdownFiles(path)
      return /\.md$|^llms-full\.txt$/.test(entry.name) ? [path] : []
    })
  )
  return files.flat()
}

/**
 * After the build: cleans the Markdown files and llms-full.txt, and puts the
 * rules for assistants at the top of llms-full.txt.
 */
export const pluginLlms = (): RspressPlugin => ({
  name: 'dotpress-llms',
  async afterBuild(config, isProd) {
    if (!isProd || config.llms === false) return
    const outDir = resolve(config.outDir ?? 'doc_build')
    for (const file of await markdownFiles(outDir)) {
      let content = cleanMarkdown(await readFile(file, 'utf8'))
      if (file.endsWith('llms-full.txt')) {
        content = [
          `# ${config.title}`,
          `> ${config.description}`,
          LLMS_GUIDANCE,
          `${SITE}/llms.txt is an index of the pages below, each also available on its own in Markdown.`,
          content,
        ].join('\n\n')
      }
      await writeFile(file, content)
    }
  },
})
